// ── Extraer datos básicos del mensaje de Telegram ────────────────────────────
const msg       = $input.first()?.json?.message ?? {};
const chatId    = msg?.chat?.id?.toString() ?? null;
const firstName = (msg?.from?.first_name ?? 'amigo').substring(0, 50);
const msgText   = (msg?.text ?? '').trim().substring(0, 2000);
const isText    = typeof msg?.text === 'string' && msg.text.trim().length > 0;
const RESET_CMDS = ['/start','/reset','/nuevo','/iniciar','/reiniciar'];
const isCommand = RESET_CMDS.includes(msgText.toLowerCase());

return [{ json: { chatId, firstName, msgText, isText, isCommand } }];

// ── TABLA REQUERIDA EN SUPABASE (ejecutar una vez) ───────────────────────────
// CREATE TABLE bot_sessions (
//   chat_id    TEXT PRIMARY KEY,
//   session    JSONB        NOT NULL DEFAULT '{}',
//   updated_at TIMESTAMPTZ  DEFAULT now(),
//   expires_at TIMESTAMPTZ  DEFAULT (now() + interval '30 minutes')
// );
// ─────────────────────────────────────────────────────────────────────────────

const msgData = $('Code: Validate Message').first()?.json ?? {};
const chatId    = msgData.chatId    ?? 'unknown';
const firstName = msgData.firstName ?? 'amigo';
const msgText   = msgData.msgText   ?? '';
const isCommand = msgData.isCommand ?? false;

// Supabase GET devuelve { body: [...] } por fullResponse:true
const supaResp = $input.first()?.json ?? {};
const rawBody  = supaResp?.body ?? supaResp ?? [];
const rows     = Array.isArray(rawBody) ? rawBody : (rawBody ? [rawBody] : []);
const dbRow    = rows.length > 0 ? rows[0] : null;
const dbSess   = dbRow?.session ?? null;

// ── Rate limit: máximo 1 mensaje por segundo por usuario ─────────────────────
if (!isCommand && dbSess?.last_msg_at) {
  const diff = Date.now() - new Date(dbSess.last_msg_at).getTime();
  if (diff < 1000) {
    return [{ json: {
      chatId, firstName, msgText,
      session: dbSess,
      sendWelcome: false, rateLimited: true,
      telegramMessage: '⏳ Un momento... envía de a un mensaje a la vez.',
      isFollowUp: false
    }}];
  }
}

// ── Determinar si es sesión nueva ────────────────────────────────────────────
const isExpired = dbRow && new Date(dbRow.expires_at) < new Date();
const isNew     = isCommand || !dbRow || isExpired;

let session;
if (isNew) {
  session = {
    ocasion: null, region: null, personas: null, preparacion: null,
    completed: false, last_msg_at: new Date().toISOString()
  };
} else {
  session = {
    ocasion:     dbSess?.ocasion     ?? null,
    region:      dbSess?.region      ?? null,
    personas:    dbSess?.personas    ?? null,
    preparacion: dbSess?.preparacion ?? null,
    completed:   dbSess?.completed   ?? false,
    last_msg_at: new Date().toISOString()
  };
}

// ── Follow-up: sesión completa, nuevo mensaje libre ──────────────────────────
const isFollowUp = !isNew && session.completed === true;

// ── Mensaje de bienvenida ────────────────────────────────────────────────────
let telegramMessage = '';
if (isNew) {
  telegramMessage =
    '👋 <b>¡Hola ' + firstName + '!</b> Soy <b>Chef Friko</b> 🍗, tu asistente culinario oficial de Friko.\n\n' +
    '¡Te ayudaré a encontrar el producto perfecto y una receta deliciosa!\n\n' +
    '🍽️ <b>¿Para qué ocasión estás cocinando?</b>\n' +
    '<i>Ej: almuerzo familiar, parrillada con amigos, cena rápida, lonchera infantil</i>\n\n' +
    '<i>Tip: puedes enviar todo en un mensaje:\n' +
    '"cena para 6 personas en Medellín, voy a hacer parrilla" ✅</i>';
}

return [{ json: {
  chatId, firstName, msgText, session, isNew, isFollowUp,
  sendWelcome: isNew, rateLimited: false, telegramMessage
}}];

// ── Leer contexto desde Init Session (no desde $input que puede ser corrompido) ──
const initData  = $('Code: Init Session').first()?.json ?? {};
const chatId    = initData.chatId     ?? 'unknown';
const firstName = initData.firstName  ?? 'amigo';
const msgText   = initData.msgText    ?? '';
const session   = { ...(initData.session ?? {}) };
const isFollowUp = initData.isFollowUp ?? false;

// ── Follow-up: enviar directo a Flowise sin recolectar datos ────────────────
if (isFollowUp) {
  return [{ json: {
    chatId, firstName, msgText, session,
    simpleResult: null, groqBody: null, needsGroq: false, isFollowUp: true
  }}];
}

const lower = msgText.toLowerCase().trim();

const NUM_WORDS = {
  'un':1,'uno':1,'una':1,'dos':2,'tres':3,'cuatro':4,'cinco':5,'seis':6,
  'siete':7,'ocho':8,'nueve':9,'diez':10,'once':11,'doce':12,'trece':13,
  'catorce':14,'quince':15,'veinte':20,'veinticinco':25,'treinta':30,
  'cuarenta':40,'cincuenta':50,'cien':100
};

const PREP_KEYS = [
  'horno','sarten','sartén','parrilla','airfryer','freidora de aire',
  'freidora','vapor','microondas','olla a presion','olla a presión',
  'olla','estufa','cualquiera','no importa','no tengo preferencia'
];

let simpleResult = null;

// Regla 1: Solo falta PERSONAS y el mensaje es un número o número en texto
if (!session.personas && session.ocasion && session.region) {
  const numRaw  = parseInt(lower.replace(/[^0-9]/g, ''), 10);
  const numWord = NUM_WORDS[lower.trim()] ?? null;
  const finalN  = (numRaw > 0 && numRaw <= 500) ? numRaw : numWord;
  if (finalN && finalN > 0 && finalN <= 500) {
    simpleResult = { personas: finalN };
  }
}

// Regla 2: Solo falta PREPARACION y el mensaje es una keyword o respuesta corta
if (!simpleResult && !session.preparacion && session.personas) {
  const found = PREP_KEYS.find(k => lower.includes(k));
  if (found) {
    simpleResult = { preparacion: found };
  } else if (lower.split(' ').length <= 4 && lower.length < 30) {
    simpleResult = { preparacion: msgText.trim() };
  }
}

if (simpleResult) {
  return [{ json: {
    chatId, firstName, msgText, session,
    simpleResult, groqBody: null, needsGroq: false, isFollowUp: false
  }}];
}

// ── Necesita Groq para NLP complejo ──────────────────────────────────────────
const systemPrompt = [
  'Eres un extractor de datos JSON para un bot culinario colombiano.',
  'Analiza el mensaje y extrae solo los campos presentes. Responde SOLO con JSON valido, sin texto extra.',
  '',
  'CAMPOS (usa null si el campo no aparece):',
  '- ocasion: string|null. La ocasion de cocina. Ej: "almuerzo familiar", "parrillada", "cena romantica".',
  '- region:  string|null. Ciudad o region de Colombia. Ej: "Antioquia", "Bogota", "Medellin".',
  '- personas: integer|null. Numero de personas. Convierte texto: "tres"=3, "para mi solo"=1, "una docena"=12.',
  '- preparacion: string|null. Metodo de coccion. Ej: "horno", "sarten", "parrilla", "airfryer", "olla".',
  '',
  'REGLAS: Sin markdown. Sin explicaciones. Solo JSON. personas debe ser entero positivo o null.',
  '',
  'EJEMPLOS:',
  '"cena para tres en Medellin" -> {"ocasion":"cena","region":"Medellin","personas":3,"preparacion":null}',
  '"almuerzo bogota 8 horno"    -> {"ocasion":"almuerzo","region":"Bogota","personas":8,"preparacion":"horno"}',
  '"parrillada antioquia"       -> {"ocasion":"parrillada","region":"Antioquia","personas":null,"preparacion":"parrilla"}'
].join('\n');

const groqBody = {
  model: 'llama-3.3-70b-versatile',
  temperature: 0,
  max_tokens: 150,
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user',   content: msgText }
  ]
};

return [{ json: {
  chatId, firstName, msgText, session,
  simpleResult: null, groqBody, needsGroq: true, isFollowUp: false
}}];

// ── Contexto siempre disponible desde Simple Extract (upstream de ambas ramas) ──
let ctxData = {};
try { ctxData = $('Code: Simple Extract').first()?.json ?? {}; } catch(e) {}

const chatId     = ctxData.chatId     ?? 'unknown';
const firstName  = ctxData.firstName  ?? 'amigo';
const msgText    = ctxData.msgText    ?? '';
const isFollowUp = ctxData.isFollowUp ?? false;

let session = {
  ocasion:     ctxData.session?.ocasion     ?? null,
  region:      ctxData.session?.region      ?? null,
  personas:    ctxData.session?.personas    ?? null,
  preparacion: ctxData.session?.preparacion ?? null,
  completed:   ctxData.session?.completed   ?? false,
  last_msg_at: new Date().toISOString()
};

// ── Follow-up: enrutar directo al RAG ────────────────────────────────────────
if (isFollowUp) {
  return [{ json: {
    chatId, firstName, session,
    step: 'followup',
    directMessage: msgText,
    nextQuestion: ''
  }}];
}

const inputData = $input.first()?.json ?? {};

if (inputData.simpleResult && Object.keys(inputData.simpleResult).length > 0) {
  // ── Ruta de extracción simple ─────────────────────────────────────────────
  const s = inputData.simpleResult;
  if (s.personas    != null) session.personas    = s.personas;
  if (s.preparacion != null) session.preparacion = s.preparacion;
  if (s.ocasion     != null) session.ocasion     = s.ocasion;
  if (s.region      != null) session.region      = s.region;

} else {
  // ── Ruta de Groq NLP ─────────────────────────────────────────────────────
  let extracted = { ocasion: null, region: null, personas: null, preparacion: null };

  try {
    const rawContent = inputData?.choices?.[0]?.message?.content ?? '{}';
    const cleaned    = rawContent.replace(/```json|```/gi, '').trim();
    const parsed     = JSON.parse(cleaned);

    if (typeof parsed?.ocasion === 'string' && parsed.ocasion.trim().length > 1)
      extracted.ocasion = parsed.ocasion.trim();
    if (typeof parsed?.region === 'string' && parsed.region.trim().length > 1)
      extracted.region = parsed.region.trim();
    if (Number.isInteger(parsed?.personas) && parsed.personas > 0 && parsed.personas <= 1000)
      extracted.personas = parsed.personas;
    if (typeof parsed?.preparacion === 'string' && parsed.preparacion.trim().length > 1)
      extracted.preparacion = parsed.preparacion.trim();
  } catch(e) {
    // Groq falló o devolvió JSON inválido — extracted queda en nulls
  }

  // Señales de corrección: sobreescribir campo ya guardado si el usuario corrige
  const CORRECTIONS = ['en realidad','mejor dicho','cambia','corrige','no ',
    'perdón','perdon','quiero','prefiero','olvidé','olvide','equivoqué','equivoque'];
  const isCorrecting = CORRECTIONS.some(sig => msgText.toLowerCase().includes(sig));

  if ((isCorrecting || !session.ocasion)     && extracted.ocasion)     session.ocasion     = extracted.ocasion;
  if ((isCorrecting || !session.region)      && extracted.region)      session.region      = extracted.region;
  if ((isCorrecting || !session.personas)    && extracted.personas)    session.personas    = extracted.personas;
  if ((isCorrecting || !session.preparacion) && extracted.preparacion) session.preparacion = extracted.preparacion;
}

// ── Determinar completitud ────────────────────────────────────────────────────
const allReady = !!(session.ocasion && session.region && session.personas && session.preparacion);
session.completed = allReady;
const step = allReady ? 'send_to_rag' : 'ask_question';

let nextQuestion = '';
if (!allReady) {
  if (!session.ocasion) {
    nextQuestion =
      '🍽️ <b>¿Para qué ocasión estás cocinando?</b>\n' +
      '<i>Ej: almuerzo familiar, parrillada con amigos, cena rápida, evento especial</i>';
  } else if (!session.region) {
    nextQuestion =
      '✅ <i>Ocasión: ' + session.ocasion + '</i>\n\n' +
      '📍 <b>¿En qué región de Colombia te encuentras?</b>\n' +
      '<i>Ej: Antioquia, Bogotá, Atlántico, Santander, Eje Cafetero, Costa Caribe</i>';
  } else if (!session.personas) {
    nextQuestion =
      '✅ <i>Región: ' + session.region + '</i>\n\n' +
      '👥 <b>¿Para cuántas personas vas a cocinar?</b>\n' +
      '<i>Solo el número, ejemplo: 4</i>';
  } else {
    nextQuestion =
      '✅ <i>Para ' + session.personas + ' persona(s)</i>\n\n' +
      '🍳 <b>¿Tipo de preparación preferida?</b>\n' +
      '<i>Ej: horno, sartén, parrilla, airfryer, freidora de aire, olla a presión</i>\n\n' +
      '<i>Si no tienes preferencia escribe: cualquiera</i>';
  }
}

return [{ json: { chatId, firstName, session, step, directMessage: '', nextQuestion } }];

// ── Leer datos de Merge & Validate (siempre upstream) ───────────────────────
let mergeData = {};
try { mergeData = $('Code: Merge & Validate').first()?.json ?? {}; } catch(e) {}

const chatId        = mergeData.chatId        ?? 'unknown';
const firstName     = mergeData.firstName     ?? 'amigo';
const session       = mergeData.session       ?? {};
const directMessage = mergeData.directMessage ?? '';

const ocasion     = session.ocasion     ?? 'no especificada';
const region      = session.region      ?? 'no especificada';
const personas    = session.personas    ?? 1;
const preparacion = session.preparacion ?? 'cualquiera';

// Consulta semántica para retrieval efectivo (NO roleplay hacia Chef Friko)
const parts = [ocasion, region, personas + ' personas'];
if (preparacion && preparacion !== 'cualquiera') parts.push(preparacion);

const semanticQuery =
  parts.join(', ') +
  '. ¿Qué producto Friko recomiendas y qué receta para ' + personas + ' persona(s)? ' +
  'Ajusta todas las cantidades exactamente para ' + personas + ' persona(s).';

const finalQuestion = directMessage || semanticQuery;

return [{ json: {
  chatId, firstName, session,
  flowisePayload: {
    question:  finalQuestion,
    sessionId: 'telegram_' + chatId
  }
}}];

// ── Leer respuesta HTTP de Flowise ───────────────────────────────────────────
const httpResponse = $input.first()?.json ?? {};

let chatId    = 'unknown';
let firstName = 'amigo';

try {
  const buildData = $('Code: Build Flowise Query').first()?.json ?? {};
  chatId    = buildData.chatId    ?? 'unknown';
  firstName = buildData.firstName ?? 'amigo';
} catch(e) { /* continuar con defaults */ }

const rawText   = (httpResponse?.text   ?? '').trim();
const rawAnswer = (httpResponse?.answer ?? '').trim();
const isHttpErr = !!(httpResponse?.error) ||
                  (typeof httpResponse?.statusCode === 'number' && httpResponse.statusCode >= 400);

function mdToHtml(text) {
  if (!text) return '';
  return text
    .replace(/&/g,               '&amp;')
    .replace(/</g,               '&lt;')
    .replace(/>/g,               '&gt;')
    .replace(/\*\*\*(.*?)\*\*\*/gs, '<b><i>$1</i></b>')
    .replace(/\*\*(.*?)\*\*/gs,    '<b>$1</b>')
    .replace(/\*(.*?)\*/gs,          '<b>$1</b>')
    .replace(/__(.*?)__/gs,          '<u>$1</u>')
    .replace(/_(.*?)_/gs,            '<i>$1</i>')
    .replace(/`(.*?)`/g,             '<code>$1</code>');
}

let success = false;
let responseText = '';

if (isHttpErr || (!rawText && !rawAnswer)) {
  responseText =
    '😔 <b>Ups, tuve un inconveniente</b> al consultar el catálogo de Friko.\n\n' +
    'Por favor intenta de nuevo escribiendo /nuevo.\n' +
    '<i>Si el problema persiste, intenta más tarde.</i>';
} else {
  success = true;
  responseText =
    mdToHtml(rawText || rawAnswer) +
    '\n\n─────────────────\n' +
    '💬 <i>¿Quieres otra recomendación?</i> Escribe /nuevo\n' +
    '🌐 Más recetas en www.momentosfriko.com';
}

return [{ json: { chatId, firstName, responseText, success } }];
